// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 seed, uint64 number, uint64 timestamp) public {
        // drive the contract's state with fuzzed inputs to widen the search space
        vm.prank(c.depositorAccount());
        c.setL1BlockValues(number, timestamp, 1, bytes32(seed), 0, bytes32(0), 0, 0);

        string memory v = c.version();
        assertTrue(
            keccak256(bytes(v)) == keccak256(bytes("1.0.0")) &&
            keccak256(bytes(v)) != keccak256(bytes("2.0.0")),
            "version must be 1.0.0"
        );
    }
}
